/* -------------------------------------------------------------------------------------------------
 * Devices
 * -----------------------------------------------------------------------------------------------*/

/** An input or output device, in the shape `VoiceControls` takes. */
export interface ChatcnAudioDevice {
  id: string
  label: string
  /** The system default, which the browser lists as `default`. */
  isDefault?: boolean
}

/* -------------------------------------------------------------------------------------------------
 * Level and band sources
 *
 * Voice components take audio levels as plain values or as getters. A number re-renders the
 * component on every change, which is fine at 20 updates a second. A getter is read once per
 * animation frame and never re-renders anything, which is what a 60 fps meter wants.
 * -----------------------------------------------------------------------------------------------*/

/** A level from 0 to 1, or a function that returns the current one. */
type ChatcnLevel = number | (() => number)

type ChatcnMicrophoneError =
  /** The user or the browser blocked the microphone. */
  | "not-allowed"
  /** No microphone, or another app holds it. */
  | "not-found"
  /** The page is not on HTTPS or localhost, or the browser has no media devices. */
  | "unsupported"
  | "unknown"

/* -------------------------------------------------------------------------------------------------
 * Size context
 * -----------------------------------------------------------------------------------------------*/

export type VoiceControlsSize = "md" | "lg"

/* -------------------------------------------------------------------------------------------------
 * VoiceControls
 * -----------------------------------------------------------------------------------------------*/

export interface VoiceControlsProps extends Omit<React.ComponentProps<"div">, "children"> {
  muted?: boolean
  onMutedChange?: (muted: boolean) => void
  /** Captions state. The toggle renders only when `onCaptionsChange` is set. */
  captions?: boolean
  onCaptionsChange?: (on: boolean) => void
  /** Input devices. The device menu beside the mic renders only when there are some. */
  microphones?: ChatcnAudioDevice[]
  microphone?: string
  onMicrophoneChange?: (id: string) => void
  /** Output devices. The speaker menu renders only when there are some. */
  speakers?: ChatcnAudioDevice[]
  speaker?: string
  onSpeakerChange?: (id: string) => void
  /** Live input level for the bars in the mic button. A getter animates without re-rendering. */
  inputLevel?: ChatcnLevel
  /** The microphone failed. The mic shows its error and a hint that says how to fix it. */
  micError?: ChatcnMicrophoneError
  /** Shows Try again in the mic hint. */
  onRetryMicrophone?: () => void
  /** `connecting` makes End read Cancel. `ended` hides End and disables the rest. */
  status?: "connecting" | "active" | "ended"
  onEnd?: () => void
  /** Label for the end button. Default End, or Cancel while connecting. */
  endLabel?: string
  disabled?: boolean
  /** md is 36 px controls; lg is 44 px, for full-screen voice. Default md. */
  size?: VoiceControlsSize
  /** Extra controls, rendered before End. Use `VoiceControlButton` to match. */
  children?: React.ReactNode
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

export type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
export type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
export function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

