/* -------------------------------------------------------------------------------------------------
 * Reduced motion
 * -----------------------------------------------------------------------------------------------*/

const REDUCED = "(prefers-reduced-motion: reduce)"

/** True when the user asked for reduced motion. Updates live when the setting changes. */
function useChatcnPrefersReducedMotion() {
  const [reduced, setReduced] = React.useState(false)
  React.useEffect(() => {
    const query = window.matchMedia?.(REDUCED)
    if (!query) return
    const update = () => setReduced(query.matches)
    update()
    query.addEventListener("change", update)
    return () => query.removeEventListener("change", update)
  }, [])
  return reduced
}

/** Heights at rest: short and uneven, so silence reads as a meter, never as an ellipsis. */
const REST = [0.4, 0.62, 0.46]

const clamp01 = (value: number) => (Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0)

/** Reads a level source. Undefined reads as silence. */
function readLevel(level: ChatcnLevel | undefined): number {
  if (level === undefined) return 0
  return clamp01(typeof level === "function" ? level() : level)
}

/** Moves `current` toward `target` with an exponential approach: critically damped, no bounce. */
function approach(current: number, target: number, rate: number, dt: number) {
  return current + (target - current) * (1 - Math.exp(-rate * dt))
}

/* -------------------------------------------------------------------------------------------------
 * Live level bars
 * -----------------------------------------------------------------------------------------------*/

const WEIGHTS = [0.6, 1, 0.72]

/**
 * Three bars driven by the input level. They are written straight to the DOM each frame, so a
 * getter never re-renders the bar. Under reduced motion they hold still at half height: the mic
 * still reads as live, the movement goes.
 */
function MicLevel({ level, silent }: { level: ChatcnLevel | undefined; silent?: boolean }) {
  const bars = React.useRef<(HTMLSpanElement | null)[]>([])
  const levelRef = React.useRef(level)
  levelRef.current = level
  const reduced = useChatcnPrefersReducedMotion()

  React.useEffect(() => {
    // Muted or failed: the bars rest, so the button keeps its width and reads as no signal.
    if (silent || reduced) {
      bars.current.forEach((el, i) => {
        if (el) el.style.scale = `1 ${silent ? REST[i] : 0.5}`
      })
      return
    }
    let raf = 0
    let last = 0
    let env = 0
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick)
      const dt = last ? Math.min(0.1, (now - last) / 1000) : 1 / 60
      last = now
      const value = readLevel(levelRef.current)
      env = approach(env, value, value > env ? 26 : 8, dt)
      bars.current.forEach((el, i) => {
        if (!el) return
        const weight = WEIGHTS[i] ?? 1
        // A little per-bar drift, so speech reads as speech and not one bouncing value.
        const jitter = 0.86 + 0.14 * Math.sin(now / 95 + i * 2.1)
        el.style.scale = `1 ${Math.max(REST[i] ?? 0.4, Math.min(1, env * weight * jitter * 1.7)).toFixed(3)}`
      })
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [reduced, silent])

  return (
    <span
      aria-hidden="true"
      data-slot="voice-controls-level"
      className="flex h-3 items-center gap-[2px]"
    >
      {WEIGHTS.map((_, i) => (
        <span
          key={i}
          ref={(el) => {
            bars.current[i] = el
          }}
          style={{ scale: `1 ${REST[i]}` }}
          className="h-full w-[2px] origin-center rounded-full bg-current"
        />
      ))}
    </span>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Root and trigger
 * -----------------------------------------------------------------------------------------------*/

/** Root. Controlled with `open` and `onOpenChange`, or uncontrolled. Modal by default. */
function Menu(props: MenuPrimitive.Root.Props) {
  return <MenuPrimitive.Root {...props} />
}

/** The button that opens the menu. Pass `render={<Button />}` to use your own element. */
function MenuTrigger(props: MenuPrimitive.Trigger.Props) {
  return <MenuPrimitive.Trigger data-slot="menu-trigger" {...props} />
}

