type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

interface ButtonProps extends React.ComponentProps<"button"> {
  variant?: ButtonVariant
  size?: ButtonSize
}

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-md": "size-8 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
  "icon-lg": "size-9 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
}

/** Class names for anything that should look like a button, such as a link. */
function buttonVariants({
  variant = "ghost",
  size = "md",
}: {
  variant?: ButtonVariant
  size?: ButtonSize
} = {}) {
  return cn(base, variants[variant], sizes[size])
}

export function Button({
  variant = "ghost",
  size = "md",
  type = "button",
  className,
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  )
}

/**
 * The call bar: mute with a live level and a device menu, speaker, captions, your own controls,
 * and End. A group with plain Tab order: every control is a primary action users reach for by
 * name, and the menus own the arrow keys.
 */
export function VoiceControls({
  muted = false,
  onMutedChange,
  captions = false,
  onCaptionsChange,
  microphones,
  microphone,
  onMicrophoneChange,
  speakers,
  speaker,
  onSpeakerChange,
  inputLevel,
  micError,
  onRetryMicrophone,
  status = "active",
  onEnd,
  endLabel,
  disabled = false,
  size = "md",
  className,
  children,
  ...props
}: VoiceControlsProps) {
  const micRef = React.useRef<HTMLButtonElement>(null)
  const [hintOpen, setHintOpen] = React.useState(false)
  React.useEffect(() => {
    setHintOpen(micError !== undefined)
  }, [micError])

  const ended = status === "ended"
  const off = disabled || ended
  const hasMics = (microphones?.length ?? 0) > 0
  const hasSpeakers = (speakers?.length ?? 0) > 0
  const lg = size === "lg"
  const errored = micError !== undefined

  const micGlyph = errored ? (
    <MicOffIcon className="text-(color:--chatcn-red)" />
  ) : muted ? (
    <MicOffIcon />
  ) : (
    <MicIcon />
  )

  return (
    <SizeContext.Provider value={size}>
      {/* biome-ignore lint/a11y/useSemanticElements: a fieldset cannot be an inline pill row */}
      <div
        role="group"
        aria-label="Call controls"
        aria-disabled={off || undefined}
        data-slot="voice-controls"
        data-voice-status={status}
        data-size={size}
        className={cn(
          "bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) inline-flex max-w-full items-center rounded-full",
          lg ? "gap-1.5 p-1.5" : "gap-1 p-1",
          className,
        )}
        {...props}
      >
        {/* Mute, with the device menu as the second half of a split button. */}
        <div data-slot="voice-controls-mic" className="flex items-center">
          <Tooltip content={errored ? ERROR_TITLES[micError] : muted ? "Unmute" : "Mute"}>
            <button
              ref={micRef}
              type="button"
              aria-label="Mute microphone"
              aria-pressed={muted}
              disabled={off}
              data-slot="voice-controls-mute"
              data-muted={muted ? "" : undefined}
              onClick={() => {
                if (errored) {
                  setHintOpen(true)
                  return
                }
                onMutedChange?.(!muted)
              }}
              className={cn(
                control,
                box[size],
                hasMics ? "rounded-s-full rounded-e-none" : "",
                lg ? "ps-3.5 pe-3" : "ps-3 pe-2.5",
                muted &&
                  !errored &&
                  "bg-(color:--chatcn-fg) text-(color:--chatcn-bg) hover:bg-(color:--chatcn-gray-900) hover:text-(color:--chatcn-bg)",
              )}
            >
              <span
                key={errored ? "error" : muted ? "muted" : "live"}
                className="flex items-center gap-1.5 motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]"
              >
                {micGlyph}
                <MicLevel level={inputLevel} silent={muted || errored} />
              </span>
            </button>
          </Tooltip>
          {hasMics ? (
            <Menu>
              <MenuTrigger
                disabled={off}
                aria-label="Choose microphone"
                data-slot="voice-controls-mic-menu"
                className={cn(
                  control,
                  box[size],
                  "data-[popup-open]:bg-(color:--chatcn-fill-hover) data-[popup-open]:text-(color:--chatcn-fg) min-w-0 rounded-s-none rounded-e-full px-1.5",
                  // Muted inverts both halves, so the split button reads as one control.
                  muted &&
                    !errored &&
                    "bg-(color:--chatcn-fg) text-(color:--chatcn-bg) hover:bg-(color:--chatcn-gray-900) hover:text-(color:--chatcn-bg) data-[popup-open]:bg-(color:--chatcn-gray-900) data-[popup-open]:text-(color:--chatcn-bg)",
                  lg ? "w-7" : "w-6",
                  "[&_svg]:size-3.5!",
                )}
              >
                <ChevronDownIcon aria-hidden="true" />
              </MenuTrigger>
              <MenuContent side="top" align="start" className="w-64">
                <DeviceMenuItems
                  label="Microphone"
                  devices={microphones ?? []}
                  value={microphone}
                  onValueChange={onMicrophoneChange}
                />
              </MenuContent>
            </Menu>
          ) : null}
        </div>

        {hasSpeakers ? (
          <Menu>
            <MenuTrigger
              disabled={off}
              aria-label="Choose speaker"
              data-slot="voice-controls-speaker"
              className={cn(
                control,
                box[size],
                "data-[popup-open]:bg-(color:--chatcn-fill-hover) data-[popup-open]:text-(color:--chatcn-fg)",
              )}
            >
              <Volume2Icon aria-hidden="true" />
            </MenuTrigger>
            <MenuContent side="top" align="center" className="w-64">
              <DeviceMenuItems
                label="Speaker"
                devices={speakers ?? []}
                value={speaker}
                onValueChange={onSpeakerChange}
              />
            </MenuContent>
          </Menu>
        ) : null}

        {onCaptionsChange ? (
          <VoiceControlButton
            label="Captions"
            tooltip={captions ? "Hide captions" : "Show captions"}
            pressed={captions}
            disabled={off}
            onClick={() => onCaptionsChange(!captions)}
          >
            <CaptionsIcon aria-hidden="true" />
          </VoiceControlButton>
        ) : null}

        {children}

        {!ended && onEnd ? (
          <button
            type="button"
            disabled={disabled}
            onClick={onEnd}
            data-slot="voice-controls-end"
            className={cn(
              control,
              box[size],
              "bg-(color:--chatcn-fg) text-(color:--chatcn-bg) hover:bg-(color:--chatcn-gray-900) hover:text-(color:--chatcn-bg) font-medium",
              "active:scale-(--chatcn-press-scale)",
              lg ? "text-[0.9375rem]/[1.5rem] tracking-[-0.006em] ms-1 ps-4 pe-5" : "text-[0.875rem]/[1.25rem] tracking-[-0.003em] ms-0.5 ps-3 pe-3.5",
            )}
          >
            <PhoneOffIcon aria-hidden="true" />
            {endLabel ?? (status === "connecting" ? "Cancel" : "End")}
          </button>
        ) : null}

        <Popover open={hintOpen && errored} onOpenChange={setHintOpen}>
          <PopoverContent
            anchor={micRef}
            side="top"
            align="start"
            sideOffset={10}
            initialFocus={false}
            finalFocus={false}
            role="alert"
            data-slot="voice-controls-mic-error"
            className="flex w-72 flex-col gap-1 p-3"
          >
            {micError ? (
              <>
                <PopoverTitle className="flex items-center gap-1.5">
                  <MicOffIcon aria-hidden="true" className="text-(color:--chatcn-red) size-4" />
                  {ERROR_TITLES[micError]}
                </PopoverTitle>
                <PopoverDescription>{microphoneErrorMessages[micError]}</PopoverDescription>
                <div className="mt-2 flex justify-end gap-1.5">
                  <PopoverClose render={<Button size="sm" variant="ghost" />}>Dismiss</PopoverClose>
                  {onRetryMicrophone && micError !== "unsupported" ? (
                    <Button
                      size="sm"
                      variant="solid"
                      onClick={() => {
                        setHintOpen(false)
                        onRetryMicrophone()
                      }}
                    >
                      Try again
                    </Button>
                  ) : null}
                </div>
              </>
            ) : null}
          </PopoverContent>
        </Popover>
      </div>
    </SizeContext.Provider>
  )
}

