      <a
        href={`https://chatcn.dev/docs/components/${slug}`}
        target="_blank"
        rel="noopener"
        className="text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg) underline underline-offset-2"
      >
        chatcn.dev
      </a>
    </p>
  )
}

/**
 * A voice call with a coding agent: live captions for both sides, the mic bars moving while you
 * talk. The pointer mutes and unmutes, turns captions off and on, then ends the call and calls
 * again. Device menus stay closed so the preview never covers itself. Click to stop the tour.
 */
export default function VoiceControlsPreview() {
  const stage = React.useRef<HTMLDivElement>(null)
  const g = useGhost(stage)
  const [touring, setTouring] = React.useState(true)
  const [muted, setMuted] = React.useState(false)
  const [captions, setCaptions] = React.useState(true)
  const [mic, setMic] = React.useState("default")
  const [out, setOut] = React.useState("default")
  const [ended, setEnded] = React.useState(false)
  const [who, setWho] = React.useState<Speaker>("agent")
  const [said, setSaid] = React.useState("")
  const [seconds, setSeconds] = React.useState(72)
  const you = useChatcnSimulatedLevel(who === "you" && !muted && !ended && said !== "", { seed: 5 })

  React.useEffect(() => {
    if (ended) return
    const id = window.setInterval(() => setSeconds((s) => s + 1), 1000)
    return () => window.clearInterval(id)
  }, [ended])

  useLoop(async (wait) => {
    const speak = async (i: number) => {
      const line = LINES[i]!
      setWho(line.who)
      const words = line.text.split(" ")
      for (let n = 1; n <= words.length; n++) {
        setSaid(words.slice(0, n).join(" "))
        await wait(WORD_MS)
      }
    }
    setEnded(false)
    setMuted(false)
    setCaptions(true)
    setSeconds(72)
    setSaid("")
    await wait(500)
    await speak(0)
    await wait(700)
    await speak(1)
    await wait(500)
    await tap(g, 'button[aria-label="Mute microphone"]', wait)
    await wait(1600)
    await tap(g, 'button[aria-label="Mute microphone"]', wait, 300)
    await wait(300)
    g.hide()
    await speak(2)
    await wait(600)
    await tap(g, 'button[aria-label="Captions"]', wait)
    await wait(1500)
    await tap(g, 'button[aria-label="Captions"]', wait, 300)
    await wait(900)
    const end = Array.from(stage.current?.querySelectorAll<HTMLElement>("button") ?? []).find(
      (b) => b.textContent?.trim() === "End",
    )
    if (end) await tap(g, end, wait)
    await wait(1600)
    const again = Array.from(stage.current?.querySelectorAll<HTMLElement>("button") ?? []).find(
      (b) => b.textContent?.trim() === "Call again",
    )
    if (again) await tap(g, again, wait)
    await wait(200)
    g.hide()
  }, touring)

  const micName = microphones.find((d) => d.id === mic)?.label
  const outName = speakers.find((d) => d.id === out)?.label

  return (
    <FitFrame minWidth="34rem">
      <div className="flex w-full flex-col items-center justify-center gap-4 p-6">
        <div
          ref={stage}
          className="relative flex w-full max-w-lg flex-col items-center gap-6 overflow-hidden px-2 py-1"
          onPointerDown={() => {
            if (!touring) return
            setTouring(false)
            g.hide()
          }}
        >
          <div className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) flex items-center gap-2 tabular-nums">
            <span
              className={
                ended
                  ? "bg-(color:--chatcn-fg-faint) size-1.5 rounded-full"
                  : "bg-(color:--chatcn-green) size-1.5 rounded-full"
              }
            />
            {ended ? "Call ended" : "Coding agent"} · {Math.floor(seconds / 60)}:{pad(seconds % 60)}
          </div>

          <div className="flex h-24 w-full flex-col items-center justify-center gap-1.5 text-center">
            {ended ? (
              <p className="text-[0.9375rem]/[1.5rem] tracking-[-0.006em] text-(color:--chatcn-fg-muted)">The agent will message you when CI is green.</p>
            ) : captions ? (
              said ? (
                <>
                  <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) font-medium">
                    {who === "agent" ? "Agent" : "You"}
                  </span>
                  <p className="text-[1.125rem]/[1.625rem] tracking-[-0.015em] text-(color:--chatcn-fg) max-w-md text-pretty">{said}</p>
                </>
              ) : null
            ) : (
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle)">Captions are off</p>
            )}
          </div>

          <div className="flex h-11 items-center">
            {ended ? (
              <Button size="sm" variant="outline" onClick={() => setEnded(false)}>
                <RotateCcwIcon />
                Call again
              </Button>
            ) : (
              <VoiceControls
                size="lg"
                muted={muted}
                onMutedChange={setMuted}
                captions={captions}
                onCaptionsChange={setCaptions}
                microphones={microphones}
                microphone={mic}
                onMicrophoneChange={setMic}
                speakers={speakers}
                speaker={out}
                onSpeakerChange={setOut}
                inputLevel={you.getLevel}
                onEnd={() => setEnded(true)}
              />
            )}
          </div>

          <p aria-live="polite" className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) h-4 text-center">
            {ended ? "" : muted ? "Muted. The agent cannot hear you." : `${micName} in, ${outName} out`}
          </p>
          <Ghost ghost={g.ghost} />
        </div>
        <MoreOn slug="voice-controls">The call bar for voice mode: mute, devices, captions, end. On</MoreOn>
      </div>
    </FitFrame>
  )
}
